   112→		name := fmt.Sprintf("src/file_%d.go", i)
   113→		abs := filepath.Join(dir, name)
   114→		if err := os.MkdirAll(filepath.Dir(abs), 0o755); err != nil {
   115→			b.Fatalf("mkdir: %v", err)
   116→		}
   117→		content := fmt.Sprintf("package main\n\nfunc f%d() {\n\treturn\n}\n", i)
   118→		if err := os.WriteFile(abs, []byte(content), 0o644); err != nil {
   119→			b.Fatalf("write: %v", err)
   120→		}
   121→		if _, err := wt.Add(name); err != nil {
   122→			b.Fatalf("add: %v", err)
